#!/usr/bin/env node
/**
 * Mechanical inventory for the agent knowledge base.
 *
 * Enumerates App Router pages/API routes, Prisma models, and lm_* tables
 * (migrations + runtime CREATE TABLE). Does not interpret semantics —
 * curated docs under docs/kb/ own that.
 *
 *   node scripts/kb-inventory.mjs --write   # regenerate generated/*.md
 *   node scripts/kb-inventory.mjs --check   # fail if generated files are stale
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const GENERATED_DIR = path.join(ROOT, 'docs/kb/generated');
const APP_DIR = path.join(ROOT, 'src/app');
const PRISMA_SCHEMA = path.join(ROOT, 'prisma/schema.prisma');
const BACKUP_CONFIG = path.join(ROOT, 'src/lib/backups/config.ts');

const HTTP_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS'];
const METHOD_NAME_RE = HTTP_METHODS.join('|');
const METHOD_RE = new RegExp(
  String.raw`export\s+(?:async\s+)?(?:function|const)\s+(${METHOD_NAME_RE})\b`,
  'g',
);

const GENERATED_BANNER =
  '<!-- GENERATED by `scripts/kb-inventory.mjs`. Do not edit by hand. Run: npm run kb:generate -->\n';

function walk(dir, acc = []) {
  if (!fs.existsSync(dir)) return acc;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === 'node_modules' || entry.name === '.next') continue;
      walk(full, acc);
    } else if (entry.isFile()) {
      acc.push(full);
    }
  }
  return acc;
}

function toPosix(p) {
  return p.split(path.sep).join('/');
}

function rel(p) {
  return toPosix(path.relative(ROOT, p));
}

function fileToRoute(absPath) {
  const posix = rel(absPath);
  const underApp = posix.replace(/^src\/app\//, '');
  const isApi = /(?:^|\/)route\.(ts|js|tsx)$/.test(underApp);
  const isPage = /(?:^|\/)page\.(tsx|ts|jsx|js)$/.test(underApp);
  if (!isApi && !isPage) return null;

  const stripped = underApp
    .replace(/\/(?:page|route)\.(tsx|ts|jsx|js)$/, '')
    .split('/')
    .filter((seg) => !(seg.startsWith('(') && seg.endsWith(')')))
    .join('/');

  const url = stripped === '' ? '/' : `/${stripped}`;
  return { kind: isApi ? 'api' : 'page', url, file: posix };
}

function classifySurface(url) {
  if (url.startsWith('/logistics') || url.startsWith('/api/logistics')) return 'logistics';
  if (url.startsWith('/work-clock') || url.startsWith('/api/work-clock')) return 'workforce';
  if (url.startsWith('/api/finance')) return 'finance';
  if (
    url.startsWith('/api/tilopay')
    || url.startsWith('/api/billing')
    || url.startsWith('/api/stripe')
  ) {
    return 'billing';
  }
  if (
    url.startsWith('/api/bot')
    || url.startsWith('/api/chat/webhook')
    || url.startsWith('/config/ai-assistant')
  ) {
    return 'bot';
  }
  if (url.startsWith('/api/cron')) return 'cron';
  if (url.startsWith('/api/auth') || url.startsWith('/auth')) return 'auth';
  if (url.startsWith('/super-admin') || url.startsWith('/api/super-admin')) return 'admin';
  if (
    url === '/'
    || url.startsWith('/home')
    || url.startsWith('/docs')
    || url.startsWith('/privacy')
    || url.startsWith('/terms')
    || url.startsWith('/data-deletion')
    || url.startsWith('/api/ping')
    || url.startsWith('/api/contact')
    || url.startsWith('/api/integration')
    || url.startsWith('/monitoring')
  ) {
    return 'public';
  }
  return 'crm';
}

function extractMethods(absPath) {
  const src = fs.readFileSync(absPath, 'utf8');
  const found = new Set();
  for (const match of src.matchAll(METHOD_RE)) {
    found.add(match[1]);
  }
  const multiAlias = src.match(/export\s*\{([^}]+)\}/g) || [];
  for (const block of multiAlias) {
    for (const method of HTTP_METHODS) {
      if (new RegExp(String.raw`\bas\s+${method}\b`).test(block)) found.add(method);
    }
  }
  return HTTP_METHODS.filter((m) => found.has(m));
}

function collectRoutes() {
  const files = walk(APP_DIR).filter((f) =>
    /\/(page|route)\.(tsx|ts|jsx|js)$/.test(toPosix(f)),
  );
  const routes = [];
  for (const file of files) {
    const parsed = fileToRoute(file);
    if (!parsed) continue;
    const methods = parsed.kind === 'api' ? extractMethods(file) : ['GET'];
    routes.push({
      ...parsed,
      methods,
      surface: classifySurface(parsed.url),
    });
  }
  routes.sort((a, b) => {
    if (a.kind !== b.kind) return a.kind.localeCompare(b.kind);
    if (a.url !== b.url) return a.url.localeCompare(b.url);
    return a.file.localeCompare(b.file);
  });
  return routes;
}

function parsePrismaModels() {
  const src = fs.readFileSync(PRISMA_SCHEMA, 'utf8');
  const models = [];
  const enums = [];
  const modelRe = /^model\s+(\w+)\s*\{([\s\S]*?)^\}/gm;
  const enumRe = /^enum\s+(\w+)\s*\{([\s\S]*?)^\}/gm;
  for (const match of src.matchAll(modelRe)) {
    const body = match[2];
    const fields = [...body.matchAll(/^\s+(\w+)\s+/gm)].map((m) => m[1]);
    models.push({
      name: match[1],
      hasTenantId: /^\s+tenantId\s+/m.test(body),
      fields: fields.filter((f) => !['@@unique', '@@index', '@@id', '@@map'].includes(f)),
    });
  }
  for (const match of src.matchAll(enumRe)) {
    const values = [...match[2].matchAll(/^\s+(\w+)\b/gm)].map((m) => m[1]);
    enums.push({ name: match[1], values });
  }
  return { models, enums };
}

function extractCreateTableName(statement) {
  const m = statement.match(
    /CREATE TABLE\s+(?:IF NOT EXISTS\s+)?(?:"|')?(lm_[a-z0-9_]+)/i,
  );
  return m ? m[1].toLowerCase() : null;
}

function collectLmTables() {
  const scanRoots = [
    path.join(ROOT, 'supabase/migrations'),
    path.join(ROOT, 'src'),
  ];
  const found = [];
  const seen = new Set();

  for (const root of scanRoots) {
    const files = walk(root).filter((f) => /\.(sql|ts|js|mjs)$/.test(f));
    for (const file of files) {
      const src = fs.readFileSync(file, 'utf8');
      const re = /CREATE TABLE\s+(?:IF NOT EXISTS\s+)?["']?lm_[a-z0-9_]+/gi;
      let match;
      while ((match = re.exec(src))) {
        const name = extractCreateTableName(match[0]);
        if (!name) continue;
        const kind = file.includes(`${path.sep}supabase${path.sep}migrations${path.sep}`)
          ? 'migration'
          : 'runtime';
        const key = `${name}|${rel(file)}|${kind}`;
        if (seen.has(key)) continue;
        seen.add(key);
        found.push({ name, source: rel(file), kind });
      }
    }
  }

  found.sort((a, b) => {
    if (a.name !== b.name) return a.name.localeCompare(b.name);
    if (a.kind !== b.kind) return a.kind.localeCompare(b.kind);
    return a.source.localeCompare(b.source);
  });
  return found;
}

function parseRequiredLmTables() {
  const src = fs.readFileSync(BACKUP_CONFIG, 'utf8');
  const block = src.match(/REQUIRED_LM_TABLES\s*=\s*\[([\s\S]*?)\]\s+as const/);
  if (!block) return [];
  return [...block[1].matchAll(/'([^']+)'/g)].map((m) => m[1]).sort();
}

function renderRoutesMd(routes) {
  const surfaces = [...new Set(routes.map((r) => r.surface))].sort();
  const lines = [
    GENERATED_BANNER,
    '# Generated route inventory',
    '',
    `Last generated from the App Router tree under \`src/app\`. ${routes.length} entries.`,
    '',
    'Semantics, auth, and data ownership live in the curated files under [`docs/kb/`](../README.md).',
    '',
    '## Counts by surface',
    '',
    '| Surface | Pages | API routes |',
    '|---|---:|---:|',
  ];
  for (const surface of surfaces) {
    const subset = routes.filter((r) => r.surface === surface);
    const pages = subset.filter((r) => r.kind === 'page').length;
    const apis = subset.filter((r) => r.kind === 'api').length;
    lines.push(`| \`${surface}\` | ${pages} | ${apis} |`);
  }
  lines.push('', '## Routes', '', '| Surface | Kind | URL | Methods | File |', '|---|---|---|---|---|');
  for (const r of routes) {
    lines.push(
      `| \`${r.surface}\` | ${r.kind} | \`${r.url}\` | ${r.methods.join(', ') || '—'} | \`${r.file}\` |`,
    );
  }
  lines.push('');
  return lines.join('\n');
}

function renderSchemaMd({ models, enums }, lmTables, requiredLm) {
  const uniqueLm = [...new Set(lmTables.map((t) => t.name))].sort();
  const requiredSet = new Set(requiredLm);
  const runtimeOnly = uniqueLm.filter(
    (name) => lmTables.some((t) => t.name === name && t.kind === 'runtime')
      && !lmTables.some((t) => t.name === name && t.kind === 'migration'),
  );
  const missingFromBackup = uniqueLm.filter((name) => !requiredSet.has(name));
  const requiredMissingFromCode = requiredLm.filter((name) => !uniqueLm.includes(name));

  const lines = [
    GENERATED_BANNER,
    '# Generated data-surface inventory',
    '',
    'Prisma models from `prisma/schema.prisma`. `lm_*` tables from `CREATE TABLE` in `supabase/migrations/` and runtime SQL in `src/`.',
    '',
    '## Prisma models',
    '',
    '| Model | `tenantId` | Source |',
    '|---|---|---|',
  ];
  for (const m of models) {
    lines.push(
      `| \`${m.name}\` | ${m.hasTenantId ? 'yes' : 'no'} | \`prisma/schema.prisma\` |`,
    );
  }
  lines.push('', '## Prisma enums', '', '| Enum | Values |', '|---|---|');
  for (const e of enums) {
    lines.push(`| \`${e.name}\` | ${e.values.map((v) => `\`${v}\``).join(', ')} |`);
  }

  lines.push(
    '',
    '## `lm_*` tables',
    '',
    `| Distinct tables | ${uniqueLm.length} |`,
    `| Backup allowlist (\`REQUIRED_LM_TABLES\`) | ${requiredLm.length} |`,
    '',
    '| Table | Kind | Source | In `REQUIRED_LM_TABLES` |',
    '|---|---|---|---|',
  );
  for (const t of lmTables) {
    lines.push(
      `| \`${t.name}\` | ${t.kind} | \`${t.source}\` | ${requiredSet.has(t.name) ? 'yes' : '**no**'} |`,
    );
  }

  lines.push('', '## Backup coverage gaps (mechanical)', '');
  if (missingFromBackup.length === 0 && requiredMissingFromCode.length === 0) {
    lines.push('No gaps: every discovered `lm_*` table is in `REQUIRED_LM_TABLES`, and vice versa.');
  } else {
    if (missingFromBackup.length) {
      lines.push(
        'Created in code/migrations but **not** in `src/lib/backups/config.ts` `REQUIRED_LM_TABLES`:',
        '',
        ...missingFromBackup.map((n) => `- \`${n}\``),
        '',
      );
    }
    if (requiredMissingFromCode.length) {
      lines.push(
        'Listed in `REQUIRED_LM_TABLES` but no `CREATE TABLE` found in migrations or `src/`:',
        '',
        ...requiredMissingFromCode.map((n) => `- \`${n}\``),
        '',
      );
    }
  }

  if (runtimeOnly.length) {
    lines.push(
      '## Runtime-only tables (no migration `CREATE TABLE`)',
      '',
      ...runtimeOnly.map((n) => `- \`${n}\``),
      '',
    );
  } else {
    lines.push('');
  }

  return lines.join('\n');
}

function ensureDir(dir) {
  fs.mkdirSync(dir, { recursive: true });
}

function buildOutputs() {
  const routes = collectRoutes();
  const prisma = parsePrismaModels();
  const lmTables = collectLmTables();
  const requiredLm = parseRequiredLmTables();
  return {
    'ROUTES.md': renderRoutesMd(routes),
    'LM_SCHEMA.md': renderSchemaMd(prisma, lmTables, requiredLm),
  };
}

function writeOutputs(outputs) {
  ensureDir(GENERATED_DIR);
  for (const [name, contents] of Object.entries(outputs)) {
    fs.writeFileSync(path.join(GENERATED_DIR, name), contents);
  }
}

function checkOutputs(outputs) {
  const mismatches = [];
  for (const [name, expected] of Object.entries(outputs)) {
    const file = path.join(GENERATED_DIR, name);
    if (!fs.existsSync(file)) {
      mismatches.push(`${name} is missing (run npm run kb:generate)`);
      continue;
    }
    const actual = fs.readFileSync(file, 'utf8');
    if (actual !== expected) {
      mismatches.push(`${name} is stale (run npm run kb:generate)`);
    }
  }
  return mismatches;
}

const mode = process.argv.includes('--check')
  ? 'check'
  : process.argv.includes('--write')
    ? 'write'
    : 'write';

const outputs = buildOutputs();

if (mode === 'check') {
  const mismatches = checkOutputs(outputs);
  if (mismatches.length) {
    console.error('kb-inventory check failed:\n' + mismatches.map((m) => `  - ${m}`).join('\n'));
    process.exit(1);
  }
  console.log('kb-inventory check passed.');
  process.exit(0);
}

writeOutputs(outputs);
console.log(
  `Wrote ${Object.keys(outputs).length} generated KB files to ${rel(GENERATED_DIR)}`,
);
